function today(){return new Date()}
function isoLocal(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function uid(){return 'f'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
document.getElementById('mfg-dv').textContent=D.dataVersion+' ('+D.updated+')';

/* season mood */
function seasonOf(m){return (m===12||m<=2)?'winter':m<=5?'spring':m<=8?'summer':'autumn'}
function applyMood(){var v='auto';try{v=localStorage.getItem('mfg.mood')||'auto'}catch(e){}$('#mfg-mood').value=v;ROOT.dataset.mood=v==='auto'?seasonOf(today().getMonth()+1):v;
 var mc=TA?null:document.querySelector('meta[name=theme-color]');if(mc)mc.content=getComputedStyle(ROOT).getPropertyValue('--hdr').trim()||'#2a3033'}
$('#mfg-mood').addEventListener('change',function(e){try{localStorage.setItem('mfg.mood',e.target.value)}catch(x){}applyMood()});

/* storage: IndexedDB, local only */
var Store=(function(){var dbp=null;
 function db(){if(dbp)return dbp;dbp=new Promise(function(res,rej){if(!window.indexedDB){rej(new Error('IndexedDB unavailable'));return}
  var r=indexedDB.open('pnw-field-guide',1);r.onupgradeneeded=function(){var d=r.result;if(!d.objectStoreNames.contains('finds')){var s=d.createObjectStore('finds',{keyPath:'id'});s.createIndex('date','date')}};
  r.onsuccess=function(){res(r.result)};r.onerror=function(){rej(r.error)}});return dbp}
 function tx(mode,fn){return db().then(function(d){return new Promise(function(res,rej){var t=d.transaction('finds',mode);var req=fn(t.objectStore('finds'));t.oncomplete=function(){res(req&&req.result)};t.onerror=function(){rej(t.error)}})})}
 return{all:function(){return tx('readonly',function(s){return s.getAll()})},put:function(f){return tx('readwrite',function(s){return s.put(f)})},del:function(id){return tx('readwrite',function(s){return s.delete(id)})}}})();
var FINDS=[];
function loadFinds(){return Store.all().then(function(a){FINDS=(a||[]).sort(function(x,y){return (y.date||'').localeCompare(x.date||'')||(y.created||'').localeCompare(x.created||'')});return FINDS}).catch(function(e){console.warn(e);FINDS=[];return FINDS})}
function findsFor(id){return FINDS.filter(function(f){return f.speciesId===id})}

/* fuzzy search */
function norm(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9 ]+/g,' ').replace(/\s+/g,' ').trim()}
function lev(a,b){if(a===b)return 0;var m=a.length,n=b.length;if(!m)return n;if(!n)return m;var p=[],i,j;for(j=0;j<=n;j++)p[j]=j;for(i=1;i<=m;i++){var prev=p[0];p[0]=i;for(j=1;j<=n;j++){var t=p[j];p[j]=Math.min(p[j]+1,p[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=t}}return p[n]}
function fuzzyScore(q,text){q=norm(q);text=norm(text);if(!q)return 0;var ix=text.indexOf(q);if(ix>=0)return 100-Math.min(40,ix);
 var words=text.split(' '),qw=q.split(' '),total=0;
 for(var k=0;k<qw.length;k++){var w=qw[k],best=0;for(var i=0;i<words.length;i++){var t=words[i];if(!t)continue;var tol=w.length<=3?0:w.length<=5?1:2;var d=lev(w,t.slice(0,w.length));if(d<=tol)best=Math.max(best,70-d*15);else{var d2=lev(w,t);if(d2<=tol)best=Math.max(best,60-d2*15)}}
  if(!best&&w.length>=4){var qi=0;for(var c=0;c<text.length&&qi<w.length;c++)if(text[c]===w[qi])qi++;if(qi===w.length)best=20}
  if(!best)return 0;total+=best}
 return total/qw.length}
function hay(s){return [s.name,s.latin,s.family,(s.aliases||[]).join(' '),catOf(s.category).label].join(' ')}
function searchSpecies(q,limit){return D.species.map(function(s){return{s:s,sc:fuzzyScore(q,hay(s))}}).filter(function(x){return x.sc>0}).sort(function(a,b){return b.sc-a.sc}).slice(0,limit||50).map(function(x){return x.s})}
