function setWalkGPS(g){walk.gps=g;var e=$('#w-gps');if(e)e.textContent=gpsText(g);youAreHere(g)}
function startWalkGPS(){stopWalkGPS();getGPS().then(setWalkGPS).catch(function(){var e=$('#w-gps');if(e&&!walk.gps)e.textContent='\ud83d\udccd GPS unavailable \u2014 finds will save without coordinates'});
 if(navigator.geolocation&&navigator.geolocation.watchPosition){try{wWatch=navigator.geolocation.watchPosition(function(p){setWalkGPS({lat:+p.coords.latitude.toFixed(6),lon:+p.coords.longitude.toFixed(6),acc:Math.round(p.coords.accuracy)})},function(){},{enableHighAccuracy:true,maximumAge:10000,timeout:30000})}catch(e){}}}
function stopWalkGPS(){if(wWatch!=null&&navigator.geolocation)navigator.geolocation.clearWatch(wWatch);wWatch=null}
