 var lh=document.getElementById('logHere');if(lh)lh.onclick=function(){var l=TA.last();if(!l){toast('Tap the map first, or long-press a spot');return}logHere(l.lat,l.lng,'point readout')};
 var fe=document.getElementById('findEdit');if(fe)fe.onclick=function(){var f=findById(document.getElementById('findSheet').dataset.find);if(!f)return;editing=f;pendingPhoto=null;TA.closeSheet();state.fromMap=true;go('journal')};
 var fg=document.getElementById('findGuide');if(fg)fg.onclick=function(){var f=findById(document.getElementById('findSheet').dataset.find);if(!f||!f.speciesId)return;TA.closeSheet();gotoSpecies(f.speciesId)};
 /* long-press (touch, pen or mouse) or right-click / Android context menu = log a find here */
 var mc=map.getContainer(),lp={t:null,x:0,y:0,fired:0,armed:false,until:0};
 function cancel(){if(lp.t){clearTimeout(lp.t);lp.t=null}}
 function fire(cx,cy,menu){lp.fired=Date.now();if(menu)lp.until=lp.fired+300;else{lp.armed=true;setTimeout(function(){lp.armed=false},2500)}var r=mc.getBoundingClientRect(),ll=map.containerPointToLatLng(L.point(cx-r.left,cy-r.top));try{if(navigator.vibrate)navigator.vibrate(15)}catch(e){}logHere(ll.lat,ll.lng,'long-press')}
 mc.addEventListener('pointerdown',function(e){if(!e.isPrimary){cancel();return}if(e.button>0||TA.tool()||(e.target.closest&&e.target.closest('.leaflet-control,.leaflet-marker-icon')))return;
  cancel();lp.x=e.clientX;lp.y=e.clientY;lp.t=setTimeout(function(){lp.t=null;fire(lp.x,lp.y)},600)});
 mc.addEventListener('pointermove',function(e){if(lp.t&&Math.abs(e.clientX-lp.x)+Math.abs(e.clientY-lp.y)>12)cancel()});
 ['pointerup','pointercancel'].forEach(function(n){mc.addEventListener(n,cancel)});
 mc.addEventListener('contextmenu',function(e){e.preventDefault();if(Date.now()-lp.fired<1500||TA.tool())return;if(e.target.closest&&e.target.closest('.leaflet-control,.leaflet-marker-icon'))return;cancel();fire(e.clientX,e.clientY,true)});
 /* the finger lift after a long-press must not 'click' whatever the guide view now shows under it */
 document.addEventListener('pointerup',function(){if(lp.armed){lp.armed=false;lp.until=Date.now()+400}},true);
